import {tasks} from './workflow.js';
export const milestones=Object.fromEntries(tasks.map(t=>[t.id,t.title]));
export function levelOf(s){return tasks.some(t=>t.level===1&&!s[t.id])?1:tasks.some(t=>t.level===2&&!s[t.id])?2:!s.planned||!s.injection?3:4}
export function newMilestones(before,after){return Object.keys(milestones).filter(k=>!before[k]&&after[k])}
export function celebrate(keys){if(!keys.length)return;let panel=document.getElementById('milestone-panel');if(!panel){panel=document.createElement('section');panel.id='milestone-panel';panel.setAttribute('role','status');document.body.append(panel)}panel.replaceChildren();const title=document.createElement('strong');title.textContent='Milestone completed!';panel.append(title);for(const k of keys){const line=document.createElement('p');line.textContent=milestones[k];panel.append(line)}const close=document.createElement('button');close.textContent='Continue';close.onclick=()=>panel.remove();panel.append(close);if(!matchMedia('(prefers-reduced-motion: reduce)').matches)for(let i=0;i<65;i++){const bit=document.createElement('i');bit.className='confetti';bit.style.cssText=`left:${Math.random()*100}vw;background:${['#3587ed','#ffcb45','#ee6a90','#58b9a6'][i%4]};animation-delay:${Math.random()*.3}s;transform:rotate(${Math.random()*360}deg)`;document.body.append(bit);setTimeout(()=>bit.remove(),2600)}}
